create table website_remediation_blueprints(id uuid not null,tenant_id uuid not null,source_diagnosis_id uuid not null,input_sha256 char(64) not null,status text not null check(status='draft'),fact_level text not null check(fact_level='F4'),batch_count integer not null check(batch_count between 1 and 3),task_count integer not null check(task_count>0),batches jsonb not null check(jsonb_typeof(batches)='array'),implementation_authorized boolean not null check(implementation_authorized=false),publication_authorized boolean not null check(publication_authorized=false),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256));
create trigger website_remediation_blueprints_append_only before update or delete on website_remediation_blueprints for each row execute function reject_immutable_mutation();create trigger website_remediation_blueprints_no_truncate before truncate on website_remediation_blueprints for each statement execute function reject_immutable_mutation();alter table website_remediation_blueprints enable row level security;alter table website_remediation_blueprints force row level security;create policy website_remediation_blueprints_tenant_isolation on website_remediation_blueprints using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
